/* ============================================================
   thaisound2.js — เสียงเครื่องดนตรีจริงชุดที่ 2 (อัดในห้องดนตรีไทยของชมรม ห้อง 512)
   ระนาดเอก (อัดครบทีละลูก) · ขลุ่ย · ซอด้วง · โทน–รำมะนา · ฉาบ
   ใช้: TS2.init(audioContext, outputNode) แล้วเรียก
     TS2.ranadKey(k,t,v)   ลูกระนาดลูกที่ k (0 = ซฺ ลูกทวน … 20 = ฟํ ลูกยอด) เสียงจริงไม่ปรับระดับ
     TS2.ranad(freq,t,v)   เลือกลูกที่ใกล้ความถี่นั้นที่สุด
     TS2.thum(k,t,v)       ระนาดทุ้ม (ลูกระนาดเอกต่ำลงหนึ่งช่วงทบ)
     TS2.khlui(freq,t,dur,v) · TS2.sor(freq,t,dur,v) · TS2.thon(k,t,v) (k 0 ติง · 1 จ๊ง · 2 ทั่ม · 3 จ๊ะ) · TS2.chab(k,t,v) (k 0–2)
   ระนาดเอก 21 ลูก ซฺลฺทฺ ดฺรฺมฺฟฺซฺลฺทฺ ดรมฟซลท ดํรํมํฟํ: ลูกฆ้องลูกที่ i (0 = ซฺ) ตรงกับลูกระนาดลูกที่ i+7 · ด = 459 Hz (ตรงกับขลุ่ยปิดหมด)
   ============================================================ */
(function(){
  'use strict';
  const SRC={"k0": "data:audio/mpeg;base64,", "k1": "data:audio/mpeg;base64,", "k2": "data:audio/mpeg;base64,", "k3": "data:audio/mpeg;base64,", "k4": "data:audio/mpeg;base64,", "k5": "data:audio/mpeg;base64,", "k6": "data:audio/mpeg;base64,", "k7": "data:audio/mpeg;base64,", "k8": "data:audio/mpeg;base64,", "k9": "data:audio/mpeg;base64,", "k10": "data:audio/mpeg;base64,", "k11": "data:audio/mpeg;base64,", "k12": "data:audio/mpeg;base64,", "k13": "data:audio/mpeg;base64,", "k14": "data:audio/mpeg;base64,", "k15": "data:audio/mpeg;base64,", "k16": "data:audio/mpeg;base64,", "k17": "data:audio/mpeg;base64,", "k18": "data:audio/mpeg;base64,", "k19": "data:audio/mpeg;base64,", "k20": "data:audio/mpeg;base64,", "k21": "data:audio/mpeg;base64,", "f462": "data:audio/mpeg;base64,", "f520": "data:audio/mpeg;base64,", "f569": "data:audio/mpeg;base64,", "f624": "data:audio/mpeg;base64,", "f692": "data:audio/mpeg;base64,", "f760": "data:audio/mpeg;base64,", "f847": "data:audio/mpeg;base64,", "s571": "data:audio/mpeg;base64,", "s599": "data:audio/mpeg;base64,", "s678": "data:audio/mpeg;base64,", "s762": "data:audio/mpeg;base64,", "s821": "data:audio/mpeg;base64,", "s898": "data:audio/mpeg;base64,", "t_a": "data:audio/mpeg;base64,", "t_b": "data:audio/mpeg;base64,", "t_c": "data:audio/mpeg;base64,", "t_d": "data:audio/mpeg;base64,", "c_1": "data:audio/mpeg;base64,", "c_2": "data:audio/mpeg;base64,", "c_3": "data:audio/mpeg;base64,"};
  const PITCH={"ranad": [["k0", 170.2], ["k1", 187.7], ["k2", 207.3], ["k3", 230.1], ["k4", 250.3], ["k5", 278.6], ["k6", 308.2], ["k7", 341.2], ["k8", 375.5], ["k9", 414.5], ["k10", 458.9], ["k11", 504.7], ["k12", 559.2], ["k13", 615.7], ["k14", 681.0], ["k15", 753.0], ["k16", 833.7], ["k17", 914.5], ["k18", 1010.7], ["k19", 1117.7], ["k20", 1230.1], ["k21", 1366.0]], "khlui": [["f462", 462], ["f520", 520], ["f569", 569], ["f624", 624], ["f692", 692], ["f760", 760], ["f847", 847]], "sor": [["s571", 571], ["s599", 599], ["s678", 678], ["s762", 762], ["s821", 821], ["s898", 898]]};
  const RK=PITCH.ranad.reduce((o,[k,f])=>{o[+k.slice(1)]=[k,f];return o},{});
  /* โทน–รำมะนา เรียงตามแถวหน้าทับกลองแขก: 0 ติง · 1 จ๊ง (แทนโจ๊ะ) · 2 ทั่ม · 3 จ๊ะ */
  const THON=['t_b','t_d','t_a','t_c'],THON_NAMES=['ติง','จ๊ง','ทั่ม','จ๊ะ'],CHAB=['c_1','c_2','c_3'];
  let AC=null,OUT=null;const B={};
  function init(ac,out){if(AC===ac)return;AC=ac;OUT=out||ac.destination;
    Object.keys(SRC).forEach(k=>{fetch(SRC[k]).then(r=>r.arrayBuffer()).then(ab=>new Promise((res,rej)=>AC.decodeAudioData(ab,res,rej))).then(b=>{
      const d=b.getChannelData(0);let m=0;for(let i=0;i<d.length;i++)m=Math.max(m,Math.abs(d[i]));let s=0;while(s<d.length&&Math.abs(d[s])<m*.04)s++;B[k]={b,off:Math.max(0,s/b.sampleRate-.002)}}).catch(()=>{})})}
  const ready=k=>!!(k?B[k]:Object.keys(SRC).every(x=>B[x]));
  function near(list,f){let best=list[0];list.forEach(x=>{if(Math.abs(Math.log(x[1]/f))<Math.abs(Math.log(best[1]/f)))best=x});return best}
  function play(key,t,v,rate,dur,out,lp){const s=B[key];if(!AC||!s)return false;t=Math.max(t||0,AC.currentTime);
    const n=AC.createBufferSource(),g=AC.createGain();n.buffer=s.b;n.playbackRate.value=rate||1;g.gain.setValueAtTime(v==null?1:v,t);
    if(dur){const len=(s.b.duration-s.off)/(rate||1);if(dur>len-.15){n.loop=true;n.loopStart=Math.min(s.b.duration-.4,s.off+.35);n.loopEnd=s.b.duration-.2}
      g.gain.setValueAtTime(v==null?1:v,t+Math.max(.05,dur-.08));g.gain.linearRampToValueAtTime(0,t+dur+.06)}
    let src=n;if(lp){const f=AC.createBiquadFilter();f.type='lowpass';f.frequency.value=lp;f.Q.value=.5;n.connect(f);src=f}
    src.connect(g);g.connect(out||OUT);n.start(t,s.off);if(dur)n.stop(t+dur+.1);return true}
  /* เลื่อนเป็นช่วงทบให้อยู่ในช่วงเสียงจริงของเครื่อง แล้วเลือกตัวอย่างที่ใกล้ที่สุด */
  function fold(f,lo,hi){while(f<lo)f*=2;while(f>hi)f/=2;return f}
  function pitched(kind,f,t,v,dur,out){const L=PITCH[kind];f=fold(f,L[0][1]*.94,L[L.length-1][1]*1.06);const [k,f0]=near(L,f);return play(k,t,v,f/f0,dur,out)}
  function ranadKey(k,t,v,out){k=Math.round(k);let r=1;while(k>21){k-=7;r*=2}while(k<0){k+=7;r/=2}const e=RK[k];return e?play(e[0],t,v==null?1:v,r,0,out):false}
  /* เสียงค้าง (ขลุ่ย ซอ หรือเสียงบริสุทธิ์) จนกว่าจะเรียก stop() */
  function sustain(kind,f,v,out){if(!AC)return{stop(){}};const t=AC.currentTime;v=v==null?1:v;const g=AC.createGain();g.connect(out||OUT);
    let n;if(kind==='sine'){n=AC.createOscillator();n.type='sine';n.frequency.value=f;g.gain.setValueAtTime(0,t);g.gain.linearRampToValueAtTime(.25*v,t+.03);n.connect(g);n.start(t)}
    else{const L=PITCH[kind];if(!L)return{stop(){}};f=fold(f,L[0][1]*.94,L[L.length-1][1]*1.06);const [k,f0]=near(L,f),sm=B[k];if(!sm)return{stop(){}};
      n=AC.createBufferSource();n.buffer=sm.b;n.playbackRate.value=f/f0;n.loop=true;n.loopStart=Math.min(sm.b.duration-.4,sm.off+.35);n.loopEnd=sm.b.duration-.2;g.gain.setValueAtTime(v,t);n.connect(g);n.start(t,sm.off)}
    return{stop(){const e=AC.currentTime;try{g.gain.cancelScheduledValues(e);g.gain.setValueAtTime(g.gain.value,e);g.gain.linearRampToValueAtTime(0,e+.08);n.stop(e+.12)}catch(x){}}}}
  const RANADF=PITCH.ranad.reduce((o,[k,f])=>{o[+k.slice(1)]=f;return o},{});
  window.TS2={init,ready,ranadKey,sustain,RANADF,THON_NAMES,
    ranad:(f,t,v,out)=>{const [k]=near(PITCH.ranad,f);return ranadKey(+k.slice(1),t,v,out)},
    thum:(k,t,v,out)=>{k=Math.round(k);while(k<0)k+=7;while(k>21)k-=7;const e=RK[k];return e?play(e[0],t,(v==null?1:v)*1.1,.5,0,out,1400):false},
    khlui:(f,t,dur,v,out)=>pitched('khlui',f,t,v,dur||.6,out),
    sor:(f,t,dur,v,out)=>pitched('sor',f,t,v,dur||.5,out),
    thon:(k,t,v,out)=>play(THON[Math.max(0,Math.min(3,k|0))],t,v,1,0,out),
    chab:(k,t,v,out)=>play(CHAB[Math.max(0,Math.min(2,k|0))],t,v,1,0,out)};
})();
